/**************************************************************************/
/*                                                                        */
/*  BOARD SUPPORT                                          RELEASE        */
/*                                                                        */
/*    irq_dispatch.c                                   Cortex-R52/GNU     */
/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    Interrupt dispatch for Cortex-R52 on the Armv8-R AEM FVP.  Called    */
/*    from __tx_irq_processing_return in entry.S, that is after            */
/*    _tx_thread_context_save has saved the interrupted context and with   */
/*    interrupts still disabled.                                          */
/*                                                                        */
/*    _tx_timer_interrupt is safe to call from C: it uses only r0-r3 and   */
/*    returns through lr like an ordinary function.                        */
/*                                                                        */
/**************************************************************************/

#include "board.h"
#include "gicv3.h"
#include "timer.h"

/* ThreadX periodic timer entry point (assembly, AAPCS-compatible).  */

extern void _tx_timer_interrupt(void);

/* Observability for the M3 checks.  board_timer_intid records the INTID that
   actually arrived -- this is how the timer PPI was identified during bring-up
   (see TIMER_PPI_INTID) and it keeps reporting it, so a platform that assigns
   the timer elsewhere shows up as an unexpected INTID rather than a silent
   absence of ticks.  */

volatile unsigned long  board_irq_count;
volatile unsigned long  board_timer_intid;
volatile unsigned long  board_spurious_count;
volatile unsigned long  board_unexpected_intid;


/* Timer PPI priority.  Only the top 5 priority bits are implemented on this
   model, so the value is a multiple of 8.  */

#define TIMER_PPI_PRIORITY      0xA0U


/**************************************************************************/
/*  board_init                                                            */
/*                                                                        */
/*  Called from _tx_initialize_low_level.  Interrupts are still masked at  */
/*  this point, so the tick cannot be delivered before the kernel is       */
/*  ready for it.                                                         */
/**************************************************************************/

void board_init(void)
{
    gicv3_init();
    gicv3_enable_ppi(TIMER_PPI_INTID, TIMER_PPI_PRIORITY);
    timer_init();
}


/**************************************************************************/
/*  board_irq_handler                                                     */
/**************************************************************************/

void board_irq_handler(void)
{
    unsigned long intid = gicv3_acknowledge();

    if (intid == GICV3_SPURIOUS_INTID)
    {
        /* No interrupt was actually pending; must not be acknowledged.  */

        board_spurious_count++;
        return;
    }

    if (intid == (unsigned long) TIMER_PPI_INTID)
    {
        board_timer_intid = intid;
        board_irq_count++;

        /* Re-arm before servicing so the next interval starts immediately;
           this also deasserts the level-sensitive timer output.  */

        timer_reload();
        _tx_timer_interrupt();
    }
    else
    {
        board_unexpected_intid = intid;
    }

    gicv3_end_of_interrupt(intid);
}
